+        URI internalStorageFile = getInternalStorageFile(internalStorageURI);
+
+        // test for an authorized execution
+        Map<String, Object> variables = Map.of(
+            "flow", Map.of(
+                "id", FLOW,
+                "namespace", NAMESPACE),
+            "execution", Map.of("id", executionId)
