+service: new-service

+provider:
+  name: aws
+  iamManagedPolicies:
+    - 'some:aws:arn:xxx:*:*'
+    - 'someOther:aws:arn:xxx:*:*'
+    - { 'Fn::Join': [':', ['arn:aws:iam:', { Ref: 'AWSAccountId' }, 'some/path']] }
+```
 ## Custom IAM Roles

 **WARNING:** You need to take care of the overall role setup as soon as you define custom roles.
