+    }
+
+    public enum Operand {
+        AND,
+        OR
+    }
+
+    @Builder
+    @Getter
+    @ExecutionFiltersConditionValidation
+    public static class Condition {
+        @NotNull
+        @PluginProperty
+        @Schema(
