+                ```
+              - field: LABEL
+                type: IS_NOT_NULL
+                value: productId
+                ```"""
+        )
+        private Field field;
+
+        @NotNull
+        @PluginProperty
+        @Schema(
+            title = "The type of condition.",
+            description = "Depending on the type, you will need to also set the `value` or `values` property."
+        )
